  disc:{ex:["I <b>used to work</b> at the port.","I <b>didn't use to go</b> to school every day.","<b>Did</b> you <b>use to have</b> a phone?"], q:[["Is it still true now?","No — it was true in the past."],["What happens to 'used' after did/didn't?","It becomes 'use' (no d)."]],
    rule:"<b>used to</b> + verbo base = hábito o estado pasado que ya no ocurre. Negativo y pregunta: <b>didn't use to / Did … use to</b>."},
